        [Fact(DisplayName = "clothing > a survivor puts on a free coat and boots between jobs, and drops them on death")]
        public void T002_a_survivor_puts_on_a_free_coat_and_boots_between_jobs_and_dr()
        {
            var state = setup(["s..C..U"]);
            var s = Js.NN(Js.Get(state.survivors, 0));
            runUntil(state, (_) => (s.body != null) && (s.feet != null));
            expect(Clothing.wearing(state, s, "coat")).toBeDefined();
            expect(Clothing.wearing(state, s, "boots")).toBeDefined();
            expect(state.items.every((i) => i.pos == null)).toBe(true);
