        [Fact(DisplayName = "clothing > a coat keeps a winter night off (no cold damage), and wears with each hour of it")]
        public void T004_a_coat_keeps_a_winter_night_off_no_cold_damage_and_wears_wit()
        {
            var cold = setup(["s......"]);
            var coated = setup(["sC....."]);
            foreach (var st in Js.Iter((List<SimState>)[cold, coated]))
            {
                runUntil(st, (_) => st.tick > 20);
            }
            expect(Js.NN(Js.Get(coated.survivors, 0)).body).not.toBeNull();
            foreach (var st in Js.Iter((List<SimState>)[cold, coated]))
            {
                st.tick = Js.I(WINTER_NIGHT);
                st.zombiesTonight = 0;
                Js.NN(Js.Get(st.survivors, 0)).rest = 99999;
                for (var i = 0; i < ((double)(2) * (Time.TICKS_PER_HOUR)); i++)
                {
                    Tick.tick(st);
                }
            }
            expect(Js.NN(Js.Get(cold.survivors, 0)).health).toBeLessThan(Health.HEALTH_MAX);
            expect(Js.NN(Js.Get(cold.survivors, 0)).thoughts.some((t) => t.kind == "cold")).toBe(true);
            expect(Js.NN(Js.Get(coated.survivors, 0)).health).toBe(Health.HEALTH_MAX);
            expect(Js.NN(Js.Get(coated.survivors, 0)).thoughts.some((t) => t.kind == "cold")).toBe(false);
            expect(Js.NN(Js.Get(coated.items, 0)).wear).toBe(2);
        }

